/**
 * Translates an aws_lb resource to Azure or GCP equivalents.
 * Dispatches internally based on load_balancer_type (application vs network).
 */
export function translateLb(ctx: TranslationContext): EngineResult {
  const attrs = ctx.resource.attributes as Record<string, unknown>;
  const lbType = (attrs['load_balancer_type'] as string | undefined) ?? 'application';

  if (ctx.targetProvider === 'azure') {
    return lbType === 'network'
      ? translateNlbToAzure(ctx)
      : translateAlbToAzure(ctx);
  }
  return lbType === 'network'
    ? translateNlbToGcp(ctx)
    : translateAlbToGcp(ctx);
}
